<script setup lang="ts">
import { ref } from 'vue'
import { useSimulationStore } from '@/stores/simulation'
import { actions } from '@/config/robots'
import type { RobotAction } from '@/types/robot'
import AppIcon from '@/components/AppIcon.vue'
const sim = useSimulationStore()
const feedback = ref('')
function execute(action: RobotAction) { feedback.value = sim.send({ type: 'action', robot: sim.selectedId, action }, `从技能库执行：${actions[action].label}`) ? `${sim.definition.name} 正在执行「${actions[action].label}」，可前往工作台观察关节运动。` : sim.error }
</script>
<template><div class="page-heading"><div><h1>动作技能库<span class="accent">.</span></h1><p>从一个动作开始，探索机器人的运动能力。</p></div><div class="segmented"><button :class="{ active: sim.selectedId === 'quadruped' }" @click="sim.select('quadruped'); feedback = ''">RV K1 机器狗</button><button :class="{ active: sim.selectedId === 'humanoid' }" @click="sim.select('humanoid'); feedback = ''">RV H1 人形</button></div></div><div class="skills-banner"><AppIcon name="layers" /><div><h2>{{ sim.definition.name }} 动作集</h2><p>所有动作直接调用当前仿真实例，与工作台同步。</p></div><span class="badge">{{ sim.definition.actions.length }} SKILLS</span></div><div v-if="feedback" class="skill-feedback" role="status">{{ feedback }}<RouterLink :to="`/${sim.selectedId}`">打开工作台 →</RouterLink></div><div v-if="sim.current.emergency || sim.snapshot.paused" class="lock-note">{{ sim.current.emergency ? '当前机器人已急停锁定，请在工作台解除后执行动作。' : '仿真已暂停，请在工作台继续仿真后执行动作。' }} <RouterLink :to="`/${sim.selectedId}`">前往工作台 →</RouterLink></div><div class="skill-grid"><article v-for="(action, index) in sim.definition.actions" :key="action" class="skill-card panel"><div class="skill-top"><span class="skill-icon"><AppIcon :name="actions[action].icon" /></span><span class="mono">{{ String(index + 1).padStart(2, '0') }}</span></div><span class="eyebrow">{{ actions[action].english.toUpperCase() }}</span><h2>{{ actions[action].label }}</h2><p>{{ actions[action].description }}</p><div class="skill-footer"><span>{{ sim.current.controlMode === 'motion' && sim.current.action === action ? '当前动作' : '运动学仿真' }}</span><button class="btn" :class="{ 'btn-primary': sim.current.controlMode === 'motion' && sim.current.action === action }" :disabled="sim.current.emergency || sim.snapshot.paused" @click="execute(action)"><AppIcon name="play" />执行动作</button></div></article></div><p class="skill-note">动作系统支持步态、机械手、独立关节与 IK；循环、速度与记录回放可在工作台调节。抓取与搬运为动作演示，对象交互和场景任务在阶段七实现。</p></template>
